<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepName;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\OidcUrlBuilder;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;
use Civi\Lughauth\Features\OAuth\User\Application\Usecase\ChangePasswordUsecase;

/**
 * Login step form that manages the self-service password recovery flow.
 *
 * The recovery flow consists of three sequential pages: (1) an email/username entry page
 * where the user requests a recovery link, (2) an informational waiting page shown
 * immediately after the request is dispatched, and (3) a code + new-password entry page
 * reached when the user clicks the recovery link in their email (the _use_code query
 * parameter pre-fills the one-time code).
 *
 * During authentication, when a username is present in the body, a time-limited recovery URL
 * is generated via OidcUrlBuilder and the change request is dispatched via ChangePasswordUsecase.
 * When a code is present instead, the code and new password are validated and, on success, the
 * user is immediately pre-authenticated and the flow continues. Both the code and the new
 * password are encrypted in the browser before transmission.
 *
 * Relationships: delegates recovery logic to ChangePasswordUsecase, uses OidcUrlBuilder to
 * construct callback URLs, calls AuthenticateUser for post-recovery pre-authentication, and
 * uses HtmlSecurer and DecorateHtml for secure rendering.
 */
class RecoverPassForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly AuthenticateUser $authenticator,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer,
        private readonly OidcUrlBuilder $urlBuilder,
        private readonly ChangePasswordUsecase $changePassword
    ) {
    }

    /**
     * Processes either a recovery request (by username) or a recovery confirmation (by code + new password).
     *
     * If the body contains a username field, a recovery link is generated and dispatched, then a
     * waiting LoginException is thrown. If the body contains a code, it is decrypted and validated;
     * on success the user is pre-authenticated directly.
     */
    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $body = $input->body ?? [];
        if (isset($body['user'])) {
            $user = $body['user'];
            $pkce = array_filter([
                'code_challenge' => $input->context->codeChallenge ?? '',
                'code_challenge_method' => $input->context->codeChallengeMethod ?? '',
            ]);
            $url = $this->urlBuilder->recoverPassUrl(
                $input->authRequest,
                $input->context->tenant,
                $input->context->state,
                $input->context->nonce,
                '&_use_code=',
                $pkce
            );
            $this->changePassword->requestForChange($url, $input->context->tenant, $user);
            throw new LoginException(AuthenticationResult::waitNewpass($url));
        }

        $code = $this->securer->decrypt($body["code"] ?? '');
        $newpass  = $this->securer->decrypt($body["new_pass"] ?? '');
        $csid = (string) ($body['csid'] ?? '');
        if ($code === null || $newpass === null) {
            throw new LoginException(auth: AuthenticationResult::waitNewpass('', 'Invalid recover request'));
        }
        $user = $this->changePassword->validateChangeRequest($input->context->tenant, $code, $newpass);
        if ($user !== null && $user !== '') {
            $updated = $input->challenges->withUsername($user);
            $auth = $this->authenticator->preAuthenticate(
                $input->authRequest,
                $updated,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce
            );
            return StepResult::proceed($auth, $updated);
        }

        throw new LoginException(auth: AuthenticationResult::waitNewpass('', 'Unable to change to password: please retry'));
    }

    /**
     * Selects and renders the appropriate recovery sub-page based on the current flow state.
     *
     * Checks the recover_send query parameter to decide whether to show the code-entry page,
     * the waiting/info page (when an error is present), or the initial username-entry page.
     */
    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $base = rtrim($input->context->baseUrl, '/') . '/oauth';
        $locale = '';
        $params = $input->request->getQueryParams();
        if (($params['recover_send'] ?? 'false') === 'true') {
            $response = $this->paintConfirm($error, $locale, $base, $input->context->tenant, $input->challenges, $input->body ?? [], $input->request, $response);
            return StepResult::render($response, $input->challenges);
        }

        if ($error) {
            $response = $this->paintWait($error, $locale, $base, $input->context->tenant, $input->challenges, $input->body ?? [], $input->request, $response);
            return StepResult::render($response, $input->challenges);
        }

        $response = $this->paintAsk($error, $locale, $base, $input->context->tenant, $input->challenges, $input->body ?? [], $input->request, $response);
        return StepResult::render($response, $input->challenges);
    }

    private function paintAsk(?AuthenticationResult $pe, string $locale, string $base, string $tenant, ChallengesState $challenges, ?array $body, ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->focusOn("user"),
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("recoverpass.ask.title");
        $errorMessage = $pe?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("recoverpass.ask.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("recoverpass.ask.help");
        $send = $translator->get("recoverpass.ask.send");
        $name = $translator->get("recoverpass.ask.username");

        $backText = $translator->get(
            "recoverpass.ask.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $translator->get("recoverpass.ask.back-label") . "\" />"]
        );
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $step = StepName::RECOVER_PASS->value;
        $response->getBody()->write($this->decorator->getFullPage(
            $request,
            'New pass',
            $js . <<<HTML
                    <h1> $title </h1>
                    <p> $help </p>
                    {$error}
                    <form method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <label>{$name}
                            <input type="text" name="user" id="user" value="" />
                        </label>
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $tenant
        ));
        return $response;
    }

    private function paintConfirm(?AuthenticationResult $pe, string $locale, string $base, string $tenant, ChallengesState $challenges, ?array $body, ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $params = $request->getQueryParams();
        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->focusOn("type_code"),
            $this->securer->cypher([['from' => 'type_code', 'to' => 'code'],
                ['from' => 'type_new_pass', 'to' => 'new_pass']], 'recform'),
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("recoverpass.code.title");
        $errorMessage = $pe?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("recoverpass.code.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("recoverpass.code.help");
        $send = $translator->get("recoverpass.code.send");
        $code = $translator->get("recoverpass.code.validation");
        $pass = $translator->get("recoverpass.code.newpass");

        $backText = $translator->get(
            "recoverpass.code.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $translator->get("recoverpass.code.back-label") . "\" />"]
        );
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $defaultCode = $params['_use_code'] ?? '';
        $step = StepName::RECOVER_PASS->value;
        $response->getBody()->write($this->decorator->getFullPage(
            $request,
            'New pass',
            $js . <<<HTML
                    <h1> $title </h1>
                    <p> $help </p>
                    {$error}
                    <form id="recform" method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <input type="hidden" name="code" id="code" value="" />
                        <input type="hidden" name="new_pass" id="new_pass" value="" />
                        <label>{$code}
                            <input type="text" id="type_code" value="{$defaultCode}" />
                        </label>
                        <label>{$pass}
                            <input type="password" id="type_new_pass" id="new_pass" value="" />
                        </label>
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $tenant
        ));
        return $response;
    }

    private function paintWait(?AuthenticationResult $pe, string $locale, string $base, string $tenant, ChallengesState $challenges, ?array $body, ServerRequestInterface $request, ResponseInterface $response): ResponseInterface
    {
        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->focusOn("type_code"),
            $this->securer->cypher([['from' => 'type_code', 'to' => 'code'],
                ['from' => 'type_new_pass', 'to' => 'new_pass']], 'recform'),
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $url = $pe?->id ?? '';
        $title = $translator->get("recoverpass.info.title");
        $errorMessage = $pe?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("recoverpass.info.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("recoverpass.info.help");
        $send = $translator->get(
            "recoverpass.info.goto-text",
            ['<a href="' . $url . '">' . $translator->get("recoverpass.info.goto-label") . '</a>' ]
        );

        $backText = $translator->get(
            "recoverpass.info.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $translator->get("recoverpass.info.back-label") . "\" />"]
        );
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $response->getBody()->write($this->decorator->getFullPage(
            $request,
            'New pass',
            $js . <<<HTML
                    <h1>{$title}</h1>
                    <p>{$help}</p>
                    {$error}
                    {$send}
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $tenant
        ));
        return $response;
    }
}
